import random, time

def solve(instance):
    n = instance['n']
    edges = instance['edges']
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))
        adj[v].append((u, w))

    rng = random.Random(20250317 + n * 97 + len(edges))
    best_score = -1
    best_side = [0] * n
    # Randomized greedy constructions followed by steepest single-vertex ascent.
    for run in range(1200):
        if run % 6 == 5:
            side = [rng.randrange(2) for _ in range(n)]
        else:
            order = list(range(n))
            rng.shuffle(order)
            side = [-1] * n
            for v in order:
                to0 = to1 = 0
                for u, w in adj[v]:
                    su = side[u]
                    if su == 0:
                        to0 += w
                    elif su == 1:
                        to1 += w
                if to0 == to1:
                    side[v] = rng.randrange(2)
                else:
                    side[v] = 0 if to0 > to1 else 1

        gain = [0] * n
        for v in range(n):
            gv = 0
            sv = side[v]
            for u, w in adj[v]:
                gv += w if side[u] == sv else -w
            gain[v] = gv

        while True:
            mg = max(gain)
            if mg <= 0:
                break
            # Randomize among tied steepest moves.
            v = rng.choice([i for i, g in enumerate(gain) if g == mg])
            old = side[v]
            side[v] ^= 1
            gain[v] = -gain[v]
            for u, w in adj[v]:
                gain[u] += -2 * w if side[u] == old else 2 * w

        score = sum(w for u, v, w in edges if side[u] != side[v])
        if score > best_score:
            best_score = score
            best_side = side[:]
    return best_side

