import random,time, math

def solver(inst, restarts=50, mode=0):
 n=inst['n']; edges=inst['edges']; adj=[[] for _ in range(n)]
 for u,v,w in edges: adj[u].append((v,w));adj[v].append((u,w))
 rng=random.Random(123)
 best=-1
 for rr in range(restarts):
  # random start or greedy
  if mode==0 or rr%3:
   p=list(range(n));rng.shuffle(p); s=[-1]*n
   for v in p:
    a=b=0
    for u,w in adj[v]:
     if s[u]>=0:
      if s[u]==0:a+=w
      else:b+=w
    # choose side with least connected weight, randomized near tie / temperature
    if a==b: s[v]=rng.randrange(2)
    else: s[v]=0 if a>b else 1
  else: s=[rng.randrange(2) for _ in range(n)]
  gains=[0]*n
  for v in range(n):
   for u,w in adj[v]: gains[v]+=w if s[u]==s[v] else -w
  # steepest hill climb, randomized ties
  while True:
   mx=max(gains)
   if mx<=0:break
   cand=[v for v,g in enumerate(gains) if g==mx]
   v=rng.choice(cand); old=s[v];s[v]^=1;gains[v]=-gains[v]
   for u,w in adj[v]: gains[u]+=(-2*w if s[u]==old else 2*w)
  val=sum(w for u,v,w in edges if s[u]!=s[v])
  if val>best: best=val;bs=s[:]
 return best,bs

for ins in INSTANCES:
 t=time.process_time(); val,_=solver(ins,100); print(ins['n'],val, sum(e[2] for e in ins['edges'])-val, time.process_time()-t)

