import random,time

def solve2(inst,restarts=100, kl=True):
 n=inst['n']; edges=inst['edges']; adj=[[] for _ in range(n)]
 for u,v,w in edges: adj[u].append((v,w));adj[v].append((u,w))
 rng=random.Random(123); best=-1
 def flip(v,s,g):
  old=s[v];s[v]^=1;g[v]=-g[v]
  for u,w in adj[v]:g[u]+=(-2*w if s[u]==old else 2*w)
 def climb(s,g):
  while 1:
   mx=max(g)
   if mx<=0:return
   v=rng.choice([i for i,x in enumerate(g) if x==mx]);flip(v,s,g)
 for rr in range(restarts):
  p=list(range(n));rng.shuffle(p);s=[-1]*n
  for v in p:
   a=b=0
   for u,w in adj[v]:
    if s[u]>=0:
     if s[u]==0:a+=w
     else:b+=w
   s[v]=(0 if a>b else 1) if a!=b else rng.randrange(2)
  g=[sum(w if s[u]==s[v] else -w for u,w in adj[v]) for v in range(n)]
  climb(s,g)
  if kl:
   for _ in range(4):
    locked=[False]*n; seq=[]; cum=0; bestcum=0; bestk=0
    for k in range(n):
     v=max((i for i in range(n) if not locked[i]),key=lambda i:g[i]); gain=g[v]
     locked[v]=True;seq.append(v);cum+=gain;flip(v,s,g)
     if cum>bestcum:bestcum=cum;bestk=k+1
    if bestk==0: # all sequence undo
     for v in reversed(seq):flip(v,s,g)
     break
    for v in reversed(seq[bestk:]):flip(v,s,g)
    climb(s,g)
  val=sum(w for u,v,w in edges if s[u]!=s[v]);best=max(best,val)
 return best
for reps in [10,100,500]:
 print('r',reps)
 for ins in INSTANCES:
  t=time.process_time(); x=solve2(ins,reps);print(x,round(time.process_time()-t,3),end='; ')
 print()

import random,time

def ils(inst, iters=5000, kick=4):
 n=inst['n']; edges=inst['edges']; adj=[[] for _ in range(n)]
 for u,v,w in edges: adj[u].append((v,w));adj[v].append((u,w))
 rng=random.Random(123); best=-1; bests=None
 def gains(s):return [sum(w if s[u]==s[v] else -w for u,w in adj[v]) for v in range(n)]
 def flip(v,s,g):
  old=s[v];s[v]^=1;g[v]=-g[v]
  for u,w in adj[v]:g[u]+=(-2*w if s[u]==old else 2*w)
 def climb(s,g):
  while 1:
   mx=max(g)
   if mx<=0:return
   v=rng.choice([i for i,x in enumerate(g) if x==mx]);flip(v,s,g)
 def val(s):return sum(w for u,v,w in edges if s[u]!=s[v])
 for rr in range(min(50,iters)):
  p=list(range(n));rng.shuffle(p);s=[-1]*n
  for v in p:
   a=b=0
   for u,w in adj[v]:
    if s[u]>=0:
     if s[u]==0:a+=w
     else:b+=w
   s[v]=(0 if a>b else 1) if a!=b else rng.randrange(2)
  g=gains(s);climb(s,g);x=val(s)
  if x>best:best=x;bests=s[:]
 s=bests[:]; g=gains(s);cur=best
 for ii in range(iters):
  # kick from best every time, maybe current on improvements
  s=bests[:]; g=gains(s)
  for v in rng.sample(range(n),kick):flip(v,s,g)
  climb(s,g);x=val(s)
  if x>best:best=x;bests=s[:]
 return best
for k in [1,2,3,4,6,8,12,16]:
 print('kick',k)
 for ins in INSTANCES:
  t=time.process_time();x=ils(ins,1000,k); print(x,round(time.process_time()-t,2),end='; ')
 print()

import random,time,math

def jacobi_eig(T, maxiter=10000):
 n=len(T); a=[row[:] for row in T]; V=[[float(i==j) for j in range(n)] for i in range(n)]
 for it in range(maxiter):
  mx=0; p=q=0
  for i in range(n):
   for j in range(i+1,n):
    x=abs(a[i][j])
    if x>mx:mx=x;p=i;q=j
  if mx<1e-10:break
  apq=a[p][q]; tau=(a[q][q]-a[p][p])/(2*apq)
  t=(1 if tau>=0 else -1)/(abs(tau)+math.sqrt(1+tau*tau))
  c=1/math.sqrt(1+t*t); ss=t*c
  app=a[p][p]; aqq=a[q][q]
  a[p][p]=app-t*apq; a[q][q]=aqq+t*apq; a[p][q]=a[q][p]=0.
  for k in range(n):
   if k!=p and k!=q:
    akp=a[k][p];akq=a[k][q]
    a[k][p]=a[p][k]=c*akp-ss*akq
    a[k][q]=a[q][k]=ss*akp+c*akq
   vkp=V[k][p];vkq=V[k][q]
   V[k][p]=c*vkp-ss*vkq;V[k][q]=ss*vkp+c*vkq
 return [a[i][i] for i in range(n)],V

def spectral(inst, iters=35):
 n=inst['n'];edges=inst['edges'];adj=[[] for _ in range(n)]
 for u,v,w in edges:adj[u].append((v,w));adj[v].append((u,w))
 rng=random.Random(321); q=[rng.gauss(0,1) for _ in range(n)];norm=math.sqrt(sum(x*x for x in q));q=[x/norm for x in q]
 Q=[];alpha=[];beta=[];prev=[0]*n; b=0
 for k in range(iters):
  z=[0.]*n
  for i in range(n):
   for j,w in adj[i]:z[i]+=w*q[j]
  if k: z=[z[i]-b*prev[i] for i in range(n)]
  a=sum(q[i]*z[i] for i in range(n)); z=[z[i]-a*q[i] for i in range(n)]
  # reorthogonalize all prior q
  for old in Q:
   d=sum(z[i]*old[i] for i in range(n))
   if abs(d)>1e-12:z=[z[i]-d*old[i] for i in range(n)]
  b=math.sqrt(sum(x*x for x in z)); Q.append(q);alpha.append(a)
  if b<1e-10:break
  beta.append(b);prev=q;q=[x/b for x in z]
 m=len(alpha);T=[[0.]*m for _ in range(m)]
 for i in range(m):
  T[i][i]=alpha[i]
  if i<m-1:T[i][i+1]=T[i+1][i]=beta[i]
 vals,V=jacobi_eig(T)
 idx=min(range(m),key=lambda i:vals[i]); x=[sum(Q[k][j]*V[k][idx] for k in range(m)) for j in range(n)]
 s=[0 if v>=0 else 1 for v in x]
 return s, vals[idx]

def eval_s(inst,s):return sum(w for u,v,w in inst['edges'] if s[u]!=s[v])
def local(inst,s, seed=42):
 n=inst['n'];adj=[[] for _ in range(n)]
 for u,v,w in inst['edges']:adj[u].append((v,w));adj[v].append((u,w))
 g=[sum(w if s[u]==s[v] else -w for u,w in adj[v]) for v in range(n)];rng=random.Random(seed)
 while max(g)>0:
  mx=max(g);v=rng.choice([i for i,x in enumerate(g) if x==mx]);old=s[v];s[v]^=1;g[v]=-g[v]
  for u,w in adj[v]:g[u]+=(-2*w if s[u]==old else 2*w)
 return s
for it in [20,35,50]:
 print('iter',it)
 for ins in INSTANCES:
  t=time.process_time();s,e=spectral(ins,it); val=eval_s(ins,s);val2=eval_s(ins,local(ins,s[:]));print(round(val),round(val2),round(time.process_time()-t,3),end='; ')
 print()

import random,time,math

def tabu(inst, iterations=10000, tenure=7, runs=1, seed=10):
 n=inst['n']; edges=inst['edges'];adj=[[] for _ in range(n)]
 for u,v,w in edges:adj[u].append((v,w));adj[v].append((u,w))
 rng=random.Random(seed);best=-1;best_s=None
 def obj(s):return sum(w for u,v,w in edges if s[u]!=s[v])
 def flip(v,s,g):
  old=s[v];s[v]^=1;g[v]=-g[v]
  for u,w in adj[v]:g[u]+=(-2*w if s[u]==old else 2*w)
 for run in range(runs):
  p=list(range(n));rng.shuffle(p);s=[-1]*n
  for v in p:
   a=b=0
   for u,w in adj[v]:
    if s[u]>=0:
     if s[u]==0:a+=w
     else:b+=w
   s[v]=(0 if a>b else 1) if a!=b else rng.randrange(2)
  g=[sum(w if s[u]==s[v] else -w for u,w in adj[v]) for v in range(n)]
  # climb first
  while max(g)>0:
   mx=max(g);v=rng.choice([i for i,x in enumerate(g) if x==mx]);flip(v,s,g)
  cur=obj(s)
  if cur>best:best=cur;best_s=s[:]
  tabu=[0]*n; tnr=tenure
  for it in range(iterations):
   # random tenure dynamic
   if it%500==0:tnr=tenure+rng.randrange(4)
   bv=-1; bg=-10**9
   for v in range(n):
    if tabu[v]<=it or cur+g[v]>best:
     if g[v]>bg: bv=v;bg=g[v]
   if bv<0: # allow smallest expiry
    bv=min(range(n),key=lambda v:tabu[v])
   cur+=g[bv];flip(bv,s,g);tabu[bv]=it+tnr+rng.randrange(3)
   if cur>best:best=cur;best_s=s[:]
 return best,best_s
for its in [1000,5000,20000,50000]:
 print('it',its)
 for ins in INSTANCES:
  t=time.process_time();x,_=tabu(ins,its,7,1,123);print(x,round(time.process_time()-t,3),end='; ')
 print()

import random,time,math

def multi(inst,mode,reps=1000):
 n=inst['n']; E=inst['edges'];adj=[[] for _ in range(n)]
 for u,v,w in E:adj[u].append((v,w));adj[v].append((u,w))
 rng=random.Random(2024);best=0; vals=[]
 def flip(v,s,g):
  old=s[v];s[v]^=1;g[v]=-g[v]
  for u,w in adj[v]:g[u]+=(-2*w if s[u]==old else 2*w)
 for r in range(reps):
  if mode==0: p=list(range(n));rng.shuffle(p);s=[-1]*n
  elif mode==1: p=sorted(range(n),key=lambda v:-len(adj[v]));rng.shuffle(p) if r%2 else None;s=[-1]*n
  elif mode==2: p=list(range(n));rng.shuffle(p);s=[rng.randrange(2) for _ in range(n)]
  elif mode==3: p=list(range(n));rng.shuffle(p);s=[-1]*n
  elif mode==4: p=list(range(n));rng.shuffle(p);s=[-1]*n
  if mode in [0,1,3,4]:
   for v in p:
    a=b=0
    for u,w in adj[v]:
     if s[u]>=0:
      if s[u]==0:a+=w
      else:b+=w
    if mode==3 and a!=b:
     # random proportional chance choose side balancing but sometimes opposite
     d=a-b; prob=1/(1+math.exp(min(20,max(-20,d/5)))) # probability side0; if side0 has more, favor 1
     s[v]=0 if rng.random()<prob else 1
    elif mode==4 and a!=b:
     d=a-b; prob=1/(1+math.exp(min(20,max(-20,d/15))))
     s[v]=0 if rng.random()<prob else 1
    else:s[v]=(0 if a>b else 1) if a!=b else rng.randrange(2)
  g=[sum(w if s[u]==s[v] else -w for u,w in adj[v]) for v in range(n)]
  while max(g)>0:
   mx=max(g);cand=[i for i,x in enumerate(g) if x==mx];v=rng.choice(cand);flip(v,s,g)
  val=sum(w for u,v,w in E if s[u]!=s[v]); vals.append(val)
  if val>best:best=val
 return best, sum(vals)/len(vals)
for mode in range(5):
 print('mode',mode)
 for ins in INSTANCES:
  t=time.process_time();x,av=multi(ins,mode,1000);print(x,round(av),round(time.process_time()-t,2),end='; ')
 print()

import random,time

def pair_search(inst,reps=100):
 n=inst['n'];E=inst['edges'];adj=[[] for _ in range(n)];wmat=[[0]*n for _ in range(n)]
 for u,v,w in E:adj[u].append((v,w));adj[v].append((u,w));wmat[u][v]=wmat[v][u]=w
 rng=random.Random(123);best=-1
 def flip(v,s,g):
  old=s[v];s[v]^=1;g[v]=-g[v]
  for u,w in adj[v]:g[u]+=(-2*w if s[u]==old else 2*w)
 def climb(s,g):
  while max(g)>0:
   mx=max(g); v=rng.choice([i for i,x in enumerate(g) if x==mx]);flip(v,s,g)
 for r in range(reps):
  p=list(range(n));rng.shuffle(p);s=[-1]*n
  for v in p:
   a=b=0
   for u,w in adj[v]:
    if s[u]>=0:
     if s[u]==0:a+=w
     else:b+=w
   s[v]=(0 if a>b else 1) if a!=b else rng.randrange(2)
  g=[sum(w if s[u]==s[v] else -w for u,w in adj[v]) for v in range(n)];climb(s,g)
  # pair search iterations
  for _ in range(20):
   bg=0;bi=bj=-1
   for i in range(n):
    for j in range(i+1,n):
     gain=g[i]+g[j]+(2*wmat[i][j] if s[i]!=s[j] else -2*wmat[i][j])
     if gain>bg:bg=gain;bi=i;bj=j
   if bi<0:break
   flip(bi,s,g);flip(bj,s,g);climb(s,g)
  val=sum(w for u,v,w in E if s[u]!=s[v]);best=max(best,val)
 return best
for reps in [10,100,500]:
 print('rep',reps)
 for ins in INSTANCES:
  t=time.process_time();x=pair_search(ins,reps);print(x,round(time.process_time()-t,2),end='; ')
 print()

import random,time,math

def anneal(inst, steps=30000, T=5, schedule=False, init='greedy', seed=123, cycles=1):
 n=inst['n'];E=inst['edges'];adj=[[] for _ in range(n)]
 for u,v,w in E:adj[u].append((v,w));adj[v].append((u,w))
 rng=random.Random(seed)
 def flip(v,s,g):
  old=s[v];s[v]^=1;g[v]=-g[v]
  for u,w in adj[v]:g[u]+=(-2*w if s[u]==old else 2*w)
 def val(s):return sum(w for u,v,w in E if s[u]!=s[v])
 if init=='greedy':
  p=list(range(n));rng.shuffle(p);s=[-1]*n
  for v in p:
   a=b=0
   for u,w in adj[v]:
    if s[u]>=0:
     if s[u]==0:a+=w
     else:b+=w
   s[v]=(0 if a>b else 1) if a!=b else rng.randrange(2)
 else:s=[rng.randrange(2) for _ in range(n)]
 g=[sum(w if s[u]==s[v] else -w for u,w in adj[v]) for v in range(n)]
 best=val(s);bs=s[:];cur=best
 for cyc in range(cycles):
  for it in range(steps):
   if schedule:
    # per cycle geometric high to low
