import random, time

def solve(instance):
    n=instance['n']; edges=instance['edges']
    adj=[[] for _ in range(n)]; total=0; deg=[0]*n
    for u,v,w in edges:
        adj[u].append((v,w)); adj[v].append((u,w)); total+=w; deg[u]+=w; deg[v]+=w
    rng=random.Random(182736+n*31+len(edges)*7+total)
    start=time.process_time(); limit=1.42
    best=-1; bestx=None
    def make_gains(x):
        return [sum(w if x[u]==x[v] else -w for u,w in adj[v]) for v in range(n)]
    def improve(x):
        gain=make_gains(x)
        while True:
            mx=0; vbest=-1; offset=rng.randrange(n)
            for j in range(n):
                v=(j+offset)%n; g=gain[v]
                if g>mx or (g==mx and g>0 and rng.random()<0.15): mx=g; vbest=v
            if vbest<0: break
            old=x[vbest]; x[vbest]=1-old; gain[vbest]=-gain[vbest]
            for u,w in adj[vbest]: gain[u]+=(-2*w if x[u]==old else 2*w)
        return x
    def score(x):
        return sum(w for u,v,w in edges if x[u]!=x[v])
    it=0
    while time.process_time()-start < 0.82:
        it+=1; x=[0]*n
        if it%5==0: x=[rng.randrange(2) for _ in range(n)]
        else:
            order=list(range(n)); rng.shuffle(order)
            if it%3==0: order.sort(key=lambda i: deg[i]+rng.random()*max(deg)*0.15, reverse=True)
            s0=[0]*n; s1=[0]*n; assigned=[False]*n
            for v in order:
                a=s0[v]; b=s1[v]
                side=(1 if a>b else 0 if b>a else rng.randrange(2))
                if rng.random()<0.08: side=1-side
                x[v]=side; assigned[v]=True
                for u,w in adj[v]:
                    if not assigned[u]:
                        if side==0:s0[u]+=w
                        else:s1[u]+=w
        improve(x); val=score(x)
        if val>best: best=val; bestx=x[:]
    # Tabu walk from the incumbent with occasional kick restarts.
    x=bestx[:]; gain=make_gains(x); cur=best
    tabu=[0]*n; t=0; lastbest=0
    while time.process_time()-start < limit:
        t+=1
        # restart from incumbent after long stagnation, kick several vertices
        if t-lastbest>180:
            x=bestx[:]
            k=rng.randint(3,9)
            for v in rng.sample(range(n),k):
                x[v]^=1
            gain=make_gains(x); cur=score(x); tabu=[0]*n; lastbest=t
        mv=-1; mg=-10**9
        offset=rng.randrange(n)
        for j in range(n):
            v=(j+offset)%n; g=gain[v]
            if tabu[v]<=t or cur+g>best:
                if g>mg: mg=g; mv=v
        if mv<0: # should be rare
            mv=rng.randrange(n); mg=gain[mv]
        old=x[mv]; x[mv]^=1; cur+=mg
        gain[mv]=-gain[mv]
        for u,w in adj[mv]: gain[u]+=(-2*w if x[u]==old else 2*w)
        tabu[mv]=t+rng.randint(5,11)
        if cur>best:
            best=cur; bestx=x[:]; lastbest=t
    return bestx

import random, time

def solve(instance):
    n=instance['n']; edges=instance['edges']; adj=[[] for _ in range(n)]; total=0; deg=[0]*n
    for u,v,w in edges:
        adj[u].append((v,w)); adj[v].append((u,w)); total+=w; deg[u]+=w; deg[v]+=w
    rng=random.Random(182736+n*31+len(edges)*7+total); start=time.process_time(); limit=1.45
    best=-1; bestx=None
    def optimize(x):
        gain=[sum(w if x[u]==x[v] else -w for u,w in adj[v]) for v in range(n)]
        # Repeat single and pair improvement
        while True:
            while True:
                mx=0; vb=-1; off=rng.randrange(n)
                for j in range(n):
                    v=(j+off)%n; g=gain[v]
                    if g>mx or (g==mx and g>0 and rng.random()<0.15): mx=g; vb=v
                if vb<0: break
                old=x[vb]; x[vb]^=1; gain[vb]=-gain[vb]
                for u,w in adj[vb]: gain[u]+=(-2*w if x[u]==old else 2*w)
            # Best adjacent pair, using joint flip gain.
            mx=0; bi=bj=-1
            for i,j,w in edges:
                corr=2*w if x[i]==x[j] else -2*w
                g=gain[i]+gain[j]-corr
                if g>mx: mx=g; bi=i; bj=j
            if bi<0: break
            # Apply flips sequentially with gain updates.
            for v in (bi,bj):
                old=x[v]; x[v]^=1; gain[v]=-gain[v]
                for u,w in adj[v]: gain[u]+=(-2*w if x[u]==old else 2*w)
        return x
    it=0
    while time.process_time()-start<limit:
        it+=1; x=[0]*n
        if it%5==0: x=[rng.randrange(2) for _ in range(n)]
        else:
            order=list(range(n)); rng.shuffle(order)
            if it%3==0: order.sort(key=lambda i:deg[i]+rng.random()*max(deg)*.15,reverse=True)
            s0=[0]*n;s1=[0]*n; assigned=[False]*n
            for v in order:
                a=s0[v];b=s1[v]; side=1 if a>b else 0 if b>a else rng.randrange(2)
                if rng.random()<.08:side=1-side
                x[v]=side;assigned[v]=True
                for u,w in adj[v]:
                    if not assigned[u]:
                        if side==0:s0[u]+=w
                        else:s1[u]+=w
        optimize(x)
        val=sum(w for u,v,w in edges if x[u]!=x[v])
        if val>best:best=val;bestx=x[:]
    return bestx

