import random,time,math

def solve(instance):
 n=instance['n']; edges=instance['edges']; adj=[[] for _ in range(n)]
 for u,v,w in edges: adj[u].append((v,w));adj[v].append((u,w))
 rng=random.Random(9137+n+len(edges)); deg=[sum(w for _,w in a) for a in adj]; deadline=time.process_time()+1.45
 best=None;bc=-1
 def init():
  x=[-1]*n; order=list(range(n));rng.shuffle(order);order.sort(key=lambda v:deg[v]+rng.random()*max(deg)*.15,reverse=True)
  for v in order:
   a=b=0
   for j,w in adj[v]:
    if x[j]>=0:
     if x[j]==0:a+=w
     else:b+=w
   x[v]=1 if a>b else 0 if b>a else rng.randrange(2)
  return x
 def improve(x):
  g=[sum(w if x[i]==x[j] else -w for j,w in adj[i]) for i in range(n)]
  while 1:
   v=max(range(n),key=g.__getitem__)
   if g[v]<=0:break
   x[v]^=1;g[v]=-g[v]
   for j,w in adj[v]:g[j]+=(-2*w if x[j]!=x[v] else 2*w)
  c=sum(w for u,v,w in edges if x[u]!=x[v])
  return c
 # multi starts part of budget
 while time.process_time()<deadline-.75:
  x=init();c=improve(x)
  if c>bc:bc=c;best=x[:]
 # annealing chains, start best or random greedy, perturb; anneal and descent
 while time.process_time()<deadline:
  if rng.random()<.75: x=best[:]
  else: x=init()
  # one heat schedule per 14000 proposals, T 18 -> .4
  g=[sum(w if x[i]==x[j] else -w for j,w in adj[i]) for i in range(n)]
  cut=sum(w for u,v,w in edges if x[u]!=x[v])
  localbest=cut; localx=x[:]
  steps=10000
  for t in range(steps):
   # geometric cooling
   temp=18.0*(0.45**(t/steps))
   v=rng.randrange(n);gain=g[v]
   if gain>=0 or rng.random()<math.exp(gain/temp):
    cut+=gain;x[v]^=1;g[v]=-gain
    for j,w in adj[v]:g[j]+=(-2*w if x[j]!=x[v] else 2*w)
    if cut>localbest:localbest=cut;localx=x[:]
  c=improve(localx)
  if c>bc:bc=c;best=localx[:]
 return best

