 deg=[sum(w for _,w in a) for a in adj];rng=random.Random(431+n);deadline=time.process_time()+1.45;best=[0]*n;bc=-1
 def opt(x):
  g=[sum(w if x[i]==x[j] else -w for j,w in adj[i]) for i in range(n)]
  while 1:
   v=max(range(n),key=g.__getitem__)
   if g[v]>0:
    x[v]^=1;g[v]=-g[v]
    for j,w in adj[v]:g[j]+=(-2*w if x[j]!=x[v] else 2*w)
    continue
   # find best positive pair move
   bp=0;pi=pj=-1
   for i in range(n):
