```python
import random
import time

def solve(instance):
    n = instance["n"]
    edges = instance["edges"]

    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))
        adj[v].append((u, w))

    rng = random.Random(9137 + n + len(edges))
    degree = [sum(w for _, w in a) for a in adj]
    deadline = time.process_time() + 1.45
    best = [0] * n
    best_cut = -1

    def improve(x):
        # Gain from flipping each vertex.
        gains = [
            sum(w if x[i] == x[j] else -w for j, w in adj[i])
            for i in range(n)
        ]

        while True:
            v = max(range(n), key=gains.__getitem__)
            if gains[v] <= 0:
                break

            x[v] ^= 1
            gains[v] = -gains[v]
            for j, w in adj[v]:
                gains[j] += -2 * w if x[j] != x[v] else 2 * w

        return sum(w for u, v, w in edges if x[u] != x[v])

    attempt = 0
    while time.process_time() < deadline:
        attempt += 1
        x = [-1] * n
        order = list(range(n))
        rng.shuffle(order)

        # Mix randomized orders with randomized degree-prioritized orders.
        if attempt % 3:
            order.sort(
                key=lambda v: degree[v] + rng.random() * max(degree) * 0.15,
                reverse=True,
            )

        # Greedily assign each vertex to maximize its cut weight to
        # already-assigned neighbors.
        for v in order:
            side0 = side1 = 0
            for j, w in adj[v]:
                if x[j] == 0:
                    side0 += w
                elif x[j] == 1:
                    side1 += w

            if side0 > side1:
                x[v] = 1
            elif side1 > side0:
                x[v] = 0
            else:
                x[v] = rng.randrange(2)

        cut = improve(x)
        if cut > best_cut:
            best_cut = cut
            best = x[:]

    return best
